static int patch_xbox_mmio_port_write(void)
{
    BlackGuestFunction function = black_resolve_guest_runtime_target(0x00272F35u);
    uint8_t *instruction;
    DWORD old_protection;
    if (!function) return 0;
    instruction = (uint8_t *)(uintptr_t)function + 0x12Cu;
    if (*instruction != 0xEEu) {
        trace_log("event=guest_rebase_failure kind=xbox_mmio_port guest=0x00273061 expected=EE actual=%02X\n", *instruction);
        return 0;
    }
    if (!VirtualProtect(instruction, 1, PAGE_EXECUTE_READWRITE, &old_protection)) return 0;
    *instruction = 0x90u;
    FlushInstructionCache(GetCurrentProcess(), instruction, 1);
    VirtualProtect(instruction, 1, old_protection, &old_protection);
    trace_log("event=xbox_mmio_port_write_patched guest=0x00273061 port=0x80C0 value=1 host=not_applicable\n");
    return *instruction == 0x90u;
}

